SELECT id, paper_position_id, wallet_position_id, symbol, close_trigger, source_signal_id, source_signal_decision, source_signal_original_decision, position_analysis_id, position_recommendation, entry_price_usdt, exit_price_usdt, stop_loss_usdt, take_profit_usdt, LEFT(close_explanation, 800) AS close_explanation_800, audited_at FROM crypto_ai.production_exit_audit WHERE paper_position_id IN (182,172,162,158,143,137) OR (symbol = 'EGLDUSDT' AND audited_at BETWEEN '2026-10-11 22:30:00' AND '2026-10-11 22:41:00') ORDER BY audited_at LIMIT 20